// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 pool, uint256 amount) public {
        address owner = address(this); // test contract deployed c, so it is the owner
        vm.assume(receiver != address(0));
        vm.assume(receiver != owner);
        vm.assume(receiver.code.length == 0); // plain EOA receiver, transfer cannot fail

        pool = bound(pool, 1, type(uint128).max);
        vm.deal(address(c), pool);
        amount = bound(amount, 1, pool);

        uint256 recvBefore = receiver.balance;
        vm.prank(owner);
        c.sendTo(receiver, amount);

        assertTrue(receiver.balance == recvBefore + amount && address(c).balance == pool - amount);
    }
}
